// <auto-imports> — generated by wire.mjs, do not edit by hand
import { getOwnedActor } from "./actors.js";
import { classAdvancementBegin, classAdvancementCancel, classAdvancementCommit, classAdvancementSubmit, getAdvancementSession } from "./advancement.js";
import { ABILITY_KEYS, ABILITY_SCORE_MAX, ABILITY_SCORE_MIN, BIOGRAPHY_TEXT_MAX, CLASS_LEVEL_MAX, CURRENCY_MAX, ITEM_QUANTITY_MAX, MODULE_ID, OFFLINE_CHANGES_SETTING, OFFLINE_OPERATION, OFFLINE_STATUS, REVOCABLE_CHANGES_SETTING } from "./constants.js";
import { compendiumSearch } from "./creation.js";
import { actorCurrencyApplyOnActor, actorItemCreate, actorItemDelete, actorItemSetQuantity } from "./items.js";
import { grantError, grantLog, grantWarn, summarizeGrantItem } from "./log.js";
import { escapeHtml, notifyGmsOfflineBatchSubmitted } from "./media.js";
import { BIOGRAPHY_ALL_KEYS, routeDocumentImg, setActorBiography } from "./sheet.js";
// </auto-imports>
import { bridgeFlag, bridgeFlags } from "./flags.js";
// Offline changes, approval log, revocable changes, appliers — extracted from mobile-bridge.js.

export function getOfflineChangesStore() {
  const raw = game.settings.get(MODULE_ID, OFFLINE_CHANGES_SETTING) ?? { batches: [] };
  const copy = foundry.utils.deepClone(raw);
  if (!Array.isArray(copy.batches)) copy.batches = [];
  return copy;
}

export async function saveOfflineChangesStore(store) {
  await game.settings.set(MODULE_ID, OFFLINE_CHANGES_SETTING, store);
}

export function normalizeOfflineName(value) {
  return String(value ?? "").trim().replace(/\s+/g, " ").toLowerCase();
}

export function coerceOfflineQuantity(change, operation) {
  const raw = change?.quantity;
  const n = Number(raw);
  if (operation === OFFLINE_OPERATION.CURRENCY_SET) {
    const q = Number.isFinite(n) ? Math.max(0, Math.floor(n)) : 0;
    return Math.min(CURRENCY_MAX, q);
  }
  if (operation === OFFLINE_OPERATION.CLASS_LEVEL_CHANGE) {
    const q = Number.isFinite(n) ? Math.floor(n) : 1;
    return Math.min(CLASS_LEVEL_MAX, Math.max(0, q));
  }
  if (operation === OFFLINE_OPERATION.ABILITY_SET) {
    const q = Number.isFinite(n) ? Math.floor(n) : 10;
    return Math.min(ABILITY_SCORE_MAX, Math.max(ABILITY_SCORE_MIN, q));
  }
  if (operation === OFFLINE_OPERATION.SHEET_OVERRIDE) {
    // A missing quantity used to fall back to 0, which silently turned
    // "proficient" into "not proficient" when a client dropped the field.
    // There is no sane default for an override value — refuse it instead.
    if (!Number.isFinite(n)) {
      throw new Error(`sheet.override '${change?.itemId ?? "?"}' requires a numeric quantity`);
    }
    // AC bonus may be negative; distances / senses stay non-negative in apply.
    return Math.min(9999, Math.max(-100, Math.floor(n)));
  }
  const isSpell = !!change?.isSpell || String(change?.itemType ?? "").toLowerCase() === "spell";
  if (!Number.isFinite(n)) {
    return operation === OFFLINE_OPERATION.ITEM_QUANTITY ? 0 : 1;
  }
  const q = Math.max(0, Math.floor(n));
  if (isSpell) return Math.max(1, q);
  if (
    operation === OFFLINE_OPERATION.ITEM_CREATE_TEXT ||
    operation === OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID
  ) {
    return Math.min(ITEM_QUANTITY_MAX, Math.max(1, q || 1));
  }
  if (operation === OFFLINE_OPERATION.ITEM_QUANTITY) {
    return Math.min(ITEM_QUANTITY_MAX, q);
  }
  return Math.min(ITEM_QUANTITY_MAX, Math.max(1, q || 1));
}

export function serializeOfflineChange(change, actorId, batchId) {
  const operation = String(change?.operation ?? "");
  if (!Object.values(OFFLINE_OPERATION).includes(operation)) {
    throw new Error(`Unsupported offline operation: ${operation}`);
  }
  if (operation === OFFLINE_OPERATION.SHEET_OVERRIDE) {
    const kind = String(change?.itemId ?? "").trim();
    if (!SHEET_OVERRIDE_KINDS.has(kind)) {
      throw new Error(
        `Unsupported sheet.override kind: ${kind || "(empty)"} — the Foundry module may be older than the app`
      );
    }
  }
  const changeId = String(change?.changeId ?? "");
  if (!changeId) throw new Error("changeId is required");
  return {
    changeId,
    batchId,
    actorId,
    operation,
    status: OFFLINE_STATUS.PENDING,
    createdAt: Number(change?.createdAt) || Date.now(),
    submittedAt: Date.now(),
    resolvedAt: null,
    rejectionReason: null,
    itemId: change?.itemId ? String(change.itemId) : null,
    uuid: change?.uuid ? String(change.uuid).trim() : "",
    name: String(change?.name ?? "").trim(),
    itemType: String(change?.itemType ?? "loot").trim() || "loot",
    quantity: coerceOfflineQuantity(change, operation),
    summary: String(change?.summary ?? "").trim(),
    isSpell: !!change?.isSpell,
    spellLevel: Math.max(0, Math.min(Math.floor(Number(change?.spellLevel) || 0), 9)),
    spellSchool: String(change?.spellSchool ?? "").trim(),
    // Level-up prep picks (content-server search while world sleeps).
    featUuid: change?.featUuid ? String(change.featUuid).trim() : "",
    featName: String(change?.featName ?? "").trim(),
    subclassUuid: change?.subclassUuid ? String(change.subclassUuid).trim() : "",
    subclassName: String(change?.subclassName ?? "").trim(),
    asiAssignments: String(change?.asiAssignments ?? "").trim(),
    // Deliberately not trimmed: biography text is user content, only length-capped.
    textValue: String(change?.textValue ?? "").slice(0, BIOGRAPHY_TEXT_MAX),
    // Trusted+ provisional apply: sheet is updated while status stays PENDING.
    priorLevel: change?.priorLevel != null && Number.isFinite(Number(change.priorLevel))
      ? Math.floor(Number(change.priorLevel))
      : null,
    // Flat-AC overrides are a direct write, so a rejection needs the value the
    // row displaced in order to put it back.
    priorFlatAc: change?.priorFlatAc != null && Number.isFinite(Number(change.priorFlatAc))
      ? Math.floor(Number(change.priorFlatAc))
      : null,
    provisional: !!change?.provisional,
    matches: []
  };
}

export async function findOfflineCompendiumMatches(change, query = null, exact = false) {
  if (change.operation !== OFFLINE_OPERATION.ITEM_CREATE_TEXT) return [];
  if (change.itemId) return [];
  const q = String(query ?? change.name ?? "").trim();
  if (q.length < 2) return [];
  const subtypeSets = change.isSpell ? [["spell"]] : [[]];
  const byUuid = new Map();
  for (const subtypes of subtypeSets) {
    const result = await compendiumSearch(q, ["Item"], subtypes, 20);
    for (const match of result.results ?? []) {
      if (match?.uuid) byUuid.set(match.uuid, match);
    }
  }
  const matches = [...byUuid.values()];
  if (!exact) return matches;
  const wanted = normalizeOfflineName(q);
  return matches.filter((entry) => normalizeOfflineName(entry.name) === wanted);
}

/**
 * Offline operations that sync straight through — applied on reconnect with no
 * GM approval and recorded to the revocable log, exactly like an online edit.
 * ability.set and sheet.override are deliberately absent: online leaves those
 * gated too, so they keep the approval path here.
 */
export const NO_APPROVAL_OFFLINE_OPS = new Set([
  OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID,
  OFFLINE_OPERATION.ITEM_CREATE_TEXT,
  OFFLINE_OPERATION.ITEM_QUANTITY,
  OFFLINE_OPERATION.CURRENCY_SET,
  OFFLINE_OPERATION.CLASS_LEVEL_CHANGE,
  OFFLINE_OPERATION.ABILITY_SET,
  OFFLINE_OPERATION.SHEET_OVERRIDE
]);

/** Current derived value of the field a sheet-override kind targets (null = non-numeric). */
export function sheetOverrideReadValue(actor, kind, token) {
  const sys = actor.system ?? {};
  switch (kind) {
    case "attributes.prof": return Number(sys.attributes?.prof ?? 0);
    case "skill.prof": return Number(sys.skills?.[token]?.value ?? 0);
    case "save.prof": return Number(sys.abilities?.[token]?.proficient ?? 0);
    case "speed.walk": return Number(sys.attributes?.movement?.walk ?? 0);
    case "speed.fly": return Number(sys.attributes?.movement?.fly ?? 0);
    case "speed.swim": return Number(sys.attributes?.movement?.swim ?? 0);
    case "speed.climb": return Number(sys.attributes?.movement?.climb ?? 0);
    case "sense.blindsight": return Number(sys.attributes?.senses?.blindsight ?? 0);
    case "sense.darkvision": return Number(sys.attributes?.senses?.darkvision ?? 0);
    case "sense.tremorsense": return Number(sys.attributes?.senses?.tremorsense ?? 0);
    case "sense.truesight": return Number(sys.attributes?.senses?.truesight ?? 0);
    default: return null; // ac.bonus/init.bonus use the delta; trait.* is non-numeric
  }
}

/**
 * Does this sheet override leave the player better off? Only gains are worth a
 * Revoke. ADD bonuses (AC, initiative) gain when the delta is positive; adding
 * a resistance/immunity is always a gain; the absolute-set kinds gain when the
 * new value beats the current one.
 */
export function sheetOverrideGain(actor, change) {
  const kind = String(change?.itemId ?? "").trim();
  const n = Math.floor(Number(change?.quantity) || 0);
  if (kind.startsWith("trait.")) return true;
  if (kind === "ac.bonus" || kind === "init.bonus") return n > 0;
  const prior = sheetOverrideReadValue(actor, kind, String(change?.summary ?? "").trim().toLowerCase());
  return prior == null ? true : n > prior;
}

/**
 * Applies one still-pending offline change on sync without approval and logs it
 * to the revocable ledger — the deferred twin of an online edit. Idempotent for
 * rows a Trusted submit already applied provisionally (an item already owned is
 * not re-created; a class already at its target is a no-op level change). The
 * gain-only / coalesce / day-page rules live in recordRevocableChange, so a
 * synced loss (a delete, a spend) simply leaves no entry.
 */
export async function finalizeOfflineChangeNoApproval(user, actorId, batch, change) {
  const actor = getOwnedActor(user, actorId);
  const finish = () => {
    change.status = OFFLINE_STATUS.APPLIED;
    change.resolvedAt = Date.now();
    change.grantError = null;
    change.provisional = false;
  };
  try {
    switch (change.operation) {
      case OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID: {
        let itemId = change.itemId;
        if (!(itemId && actor.items.get(itemId))) {
          const created = await actorItemCreate(user, actorId, change.uuid, change.name);
          itemId = created?.itemId ?? null;
          change.itemId = itemId;
        }
        await recordRevocableChange(actor, user, `Added "${change.name ?? itemId}"`,
          { operation: "item.create", itemId });
        finish();
        return;
      }
      case OFFLINE_OPERATION.ITEM_CREATE_TEXT: {
        let itemId = change.itemId;
        if (!(itemId && actor.items.get(itemId))) {
          const created = await actorItemCreateCustom(user, actorId, change);
          itemId = created?.itemId ?? null;
          change.itemId = itemId;
        }
        await recordRevocableChange(actor, user, `Added "${change.name ?? itemId}"`,
          { operation: "item.create", itemId });
        finish();
        return;
      }
      case OFFLINE_OPERATION.ITEM_QUANTITY: {
        const item = change.itemId ? actor.items.get(change.itemId) : null;
        const prior = item ? Number(item.system?.quantity) : null;
        const name = item?.name ?? "item";
        const res = await actorItemSetQuantity(user, actorId, change.itemId, change.quantity);
        if (!res?.deleted) {
          await recordRevocableChange(actor, user, `Set "${name}" quantity to ${res?.quantity}`,
            { operation: "item.quantity", itemId: change.itemId, prior, newValue: res?.quantity });
        }
        finish();
        return;
      }
      case OFFLINE_OPERATION.CURRENCY_SET: {
        const key = String(change.itemId ?? "").trim();
        if (!key) throw new Error("currency key is required");
        const prior = Number(actor.system?.currency?.[key] ?? 0) || 0;
        const res = await actorCurrencyApplyOnActor(actor, key, change.quantity);
        await recordRevocableChange(actor, user, `Set ${key} to ${res?.quantity}`,
          { operation: "currency.set", key, prior, newValue: res?.quantity });
        finish();
        return;
      }
      case OFFLINE_OPERATION.CLASS_LEVEL_CHANGE: {
        const classItem = actor.items.get(change.itemId);
        const result = await applyOfflineClassLevelChange(user, actorId, change, batch);
        const priorLevel = change.priorLevel != null ? change.priorLevel : result.priorLevel;
        const newLevel = Math.max(0, Math.floor(Number(classItem?.system?.levels) || 0));
        await recordRevocableChange(actor, user,
          `${classItem?.name ?? "Class"}: level ${priorLevel} → ${newLevel}`,
          { operation: "class.level", classId: change.itemId, priorLevel, newLevel });
        finish();
        return;
      }
      case OFFLINE_OPERATION.ABILITY_SET: {
        const key = String(change.itemId ?? "").toLowerCase();
        const prior = Number(actor.system?.abilities?.[key]?.value ?? 10) || 10;
        await applyOfflineAbilitySet(user, actorId, change);
        const newValue = Math.floor(Number(change.quantity) || prior);
        await recordRevocableChange(actor, user, `${key.toUpperCase()} → ${newValue}`,
          { operation: "ability.set", key, prior, newValue });
        finish();
        return;
      }
      case OFFLINE_OPERATION.SHEET_OVERRIDE: {
        const gain = sheetOverrideGain(actor, change);
        await applyOfflineSheetOverride(user, actorId, change);
        if (gain) {
          const label = String(change.name ?? "").trim() || `${change.itemId}`;
          await recordRevocableChange(actor, user, label, {
            operation: "sheet.override",
            kind: change.itemId,
            overrideChangeId: change.changeId,
            priorFlatAc: change.priorFlatAc ?? null,
            replacedEffects: change.replacedEffects ?? null
          });
        }
        finish();
        return;
      }
      default:
        return; // left on the approval path
    }
  } catch (err) {
    grantError("offline.finalize failed", {
      changeId: change.changeId,
      operation: change.operation,
      err: String(err?.message ?? err)
    }, err);
    change.grantError = String(err?.message ?? err);
  }
}

export async function offlineChangesSubmitBatch(user, actorId, batchId, changes) {
  const actor = getOwnedActor(user, actorId);
  grantLog("offline.submitBatch.start", {
    user: user?.name,
    userId: user?.id,
    role: user?.role,
    isGM: !!user?.isGM,
    actorId,
    actorName: actor?.name,
    batchId,
    changeCount: Array.isArray(changes) ? changes.length : -1,
    changes: Array.isArray(changes)
      ? changes.map((c) => ({
        changeId: c?.changeId,
        operation: c?.operation,
        uuid: c?.uuid || null,
        name: c?.name || null,
        itemType: c?.itemType || null,
        itemId: c?.itemId || null,
        status: c?.status || null
      }))
      : null
  });
  if (!batchId || typeof batchId !== "string") throw new Error("batchId is required");
  if (!Array.isArray(changes)) throw new Error("changes must be an array");

  const store = getOfflineChangesStore();
  let batch = store.batches.find((b) => b.batchId === batchId);
  if (!batch) {
    batch = {
      batchId,
      userId: user.id,
      userName: user.name,
      actorId,
      actorName: actor.name,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      changes: []
    };
    store.batches.push(batch);
  }
  if (batch.userId !== user.id || batch.actorId !== actorId) {
    throw new Error("batchId belongs to a different actor or user");
  }

  for (const incoming of changes) {
    const incomingId = String(incoming?.changeId ?? "").trim();
    // Re-edits may arrive under a new client batchId — find the pending row
    // by changeId across this user's actor batches so we don't orphan duplicates.
    let existing = null;
    let existingBatch = null;
    if (incomingId) {
      for (const b of store.batches) {
        if (b.userId !== user.id || b.actorId !== actorId) continue;
        const hit = b.changes.find((c) => c.changeId === incomingId);
        if (hit) {
          existing = hit;
          existingBatch = b;
          break;
        }
      }
    }
    let change;
    let updatedExisting = false;
    if (existing && existingBatch && existing.status === OFFLINE_STATUS.PENDING) {
      const priorItemId = existing.itemId;
      const refreshed = serializeOfflineChange(incoming, actorId, existingBatch.batchId);
      Object.assign(existing, refreshed, {
        changeId: existing.changeId,
        batchId: existingBatch.batchId,
        status: OFFLINE_STATUS.PENDING,
        resolvedAt: null,
        rejectionReason: null,
        // Keep provisional owned item / level / flat-AC snapshot from a prior
        // submit: a re-edit must still be able to roll back to the value the
        // very first submit displaced, not to its own intermediate result.
        itemId: priorItemId || refreshed.itemId,
        priorLevel: existing.priorLevel ?? refreshed.priorLevel,
        priorFlatAc: existing.priorFlatAc ?? refreshed.priorFlatAc,
        replacedEffects: existing.replacedEffects ?? null,
        provisional: existing.provisional || refreshed.provisional
      });
      change = existing;
      existingBatch.updatedAt = Date.now();
      updatedExisting = true;
    } else {
      // Resolved changeId reuse (or no prior row): always create a fresh pending entry.
      // Never silently skip — that hid approvals after a previous apply/reject.
      const freshIncoming = (existing && existing.status !== OFFLINE_STATUS.PENDING)
        ? { ...incoming, changeId: foundry.utils.randomID() }
        : incoming;
      change = serializeOfflineChange(freshIncoming, actorId, batchId);
      batch.changes.push(change);
    }
    if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_TEXT && !change.itemId) {
      change.matches = await findOfflineCompendiumMatches(change, null, true);
    } else if (!updatedExisting) {
      change.matches = [];
    }
    // UUID grants (items / spells / feats): Trusted+ get a provisional sheet copy
    // while staying PENDING; below Trusted stay queue-only until GM Approve.
    if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID && change.uuid) {
      const trusted = isTrustedBridgeUser(user);
      const actorForGrant = getOwnedActor(user, actorId);
      const alreadyOwned = change.itemId ? actorForGrant.items.get(change.itemId) : null;
      grantLog("offline.uuidGrant", {
        changeId: change.changeId,
        uuid: change.uuid,
        name: change.name,
        itemType: change.itemType,
        priorItemId: change.itemId || null,
        alreadyOwned: !!alreadyOwned,
        alreadyOwnedSummary: alreadyOwned ? summarizeGrantItem(alreadyOwned, "alreadyOwned") : null,
        role: user?.role,
        trusted
      });
      if (!trusted) {
        grantLog("offline.uuidGrant.queueOnly (below Trusted)", { changeId: change.changeId });
      } else if (alreadyOwned) {
        change.provisional = true;
        grantLog("offline.uuidGrant.alreadyOwned → stay PENDING", { changeId: change.changeId });
      } else {
        try {
          const created = await actorItemCreate(user, actorId, change.uuid, change.name);
          if (created?.itemId) change.itemId = created.itemId;
          change.provisional = true;
          change.grantError = null;
          grantLog("offline.uuidGrant.created → PENDING for GM", {
            changeId: change.changeId,
            itemId: change.itemId,
            status: change.status,
            created
          });
        } catch (err) {
          grantError("offline.uuidGrant failed", {
            changeId: change.changeId,
            uuid: change.uuid,
            name: change.name,
            err: String(err?.message ?? err)
          }, err);
          change.grantError = String(err?.message ?? err);
        }
      }
    }
    // Deletes do not need GM approval — apply immediately on submit.
    if (change.operation === OFFLINE_OPERATION.ITEM_DELETE && change.itemId) {
      try {
        await actorItemDelete(user, actorId, change.itemId);
        change.status = OFFLINE_STATUS.APPLIED;
        change.resolvedAt = Date.now();
        grantLog("offline.delete auto-applied", {
          changeId: change.changeId,
          itemId: change.itemId,
          name: change.name
        });
      } catch (err) {
        grantError("offline.delete failed", {
          changeId: change.changeId,
          itemId: change.itemId,
          err: String(err?.message ?? err)
        }, err);
        change.grantError = String(err?.message ?? err);
      }
    }
    // Level-ups: Trusted+ apply provisionally (stay PENDING; Reject rolls back).
    // Below Trusted: queue only until GM Approve.
    if (change.operation === OFFLINE_OPERATION.CLASS_LEVEL_CHANGE && change.itemId) {
      if (!isTrustedBridgeUser(user)) {
        grantLog("offline.levelChange.queueOnly (below Trusted)", {
          changeId: change.changeId,
          classId: change.itemId,
          target: change.quantity
        });
      } else {
        try {
          const result = await applyOfflineClassLevelChange(user, actorId, change, batch);
          if (change.priorLevel == null) change.priorLevel = result.priorLevel;
          change.provisional = true;
          change.grantError = null;
          grantLog("offline.levelChange.provisional → PENDING for GM", {
            changeId: change.changeId,
            classId: change.itemId,
            priorLevel: change.priorLevel,
            target: change.quantity,
            applied: result.applied
          });
        } catch (err) {
          console.warn(`[${MODULE_ID}] provisional class.levelChange failed:`, err);
          change.grantError = String(err?.message ?? err);
        }
      }
    }
    // Biography: applied here for everyone, no approval and no role check. These
    // fields are flavour text the owner can already edit in their own browser sheet,
    // so getOwnedActor above is the whole gate — unlike the sheet overrides below,
    // nothing here changes what the character can do. Written one key at a time, so
    // a browser edit to a different field made while the phone was offline survives.
    // Both outcomes are terminal: a biography row must never be left PENDING, or it
    // would appear in the GM approval dialog.
    if (change.operation === OFFLINE_OPERATION.BIOGRAPHY_SET) {
      const field = String(change.itemId ?? "");
      try {
        if (!BIOGRAPHY_ALL_KEYS.has(field)) throw new Error(`Unknown biography field: ${field}`);
        await setActorBiography(user, actorId, { [field]: change.textValue });
        change.status = OFFLINE_STATUS.APPLIED;
        change.resolvedAt = Date.now();
        change.grantError = null;
        grantLog("offline.biography auto-applied", {
          changeId: change.changeId,
          field,
          length: change.textValue.length
        });
      } catch (err) {
        grantError("offline.biography failed", {
          changeId: change.changeId,
          field,
          err: String(err?.message ?? err)
        }, err);
        change.status = OFFLINE_STATUS.REJECTED;
        change.resolvedAt = Date.now();
        change.rejectionReason = String(err?.message ?? err);
        change.grantError = String(err?.message ?? err);
      }
    }
    // Sheet overrides and ability scores are applied in the no-approval pass
    // below (finalizeOfflineChangeNoApproval), for everyone, and logged to the
    // revocable ledger. They are deliberately NOT applied here: the sheet-
    // override gain check reads the actor's live value, so it must run before
    // the effect lands, not after a provisional apply would have moved it.
  }

  // No-approval sync: apply the opened operations now, for everyone, and log
  // them to the revocable ledger — the same result as editing online, only
  // deferred to reconnect. Ability scores and sheet overrides fall through and
  // keep the approval path below.
  for (const change of batch.changes) {
    if (change.status !== OFFLINE_STATUS.PENDING) continue;
    if (NO_APPROVAL_OFFLINE_OPS.has(change.operation)) {
      await finalizeOfflineChangeNoApproval(user, actorId, batch, change);
    }
  }

  batch.updatedAt = Date.now();
  await saveOfflineChangesStore(store);

  // A page per request, in the character's own log. Written after the store is
  // saved: a log entry describing a request that failed to persist would be
  // worse than no entry at all. Only the rows still awaiting a GM decision
  // (ability scores, sheet overrides) land here now — the rest applied above.
  for (const change of batch.changes) {
    if (change.status === OFFLINE_STATUS.PENDING) {
      await writeApprovalLogEntry(actor, batch, change);
    }
  }

  // Notify when ANY of this user's actor batches still has pending rows (re-edit
  // may have updated an older batch, not the one created for this submit).
  const pendingLeft = store.batches.some((b) =>
    b.userId === user.id
    && b.actorId === actorId
    && b.changes.some((c) => c.status === OFFLINE_STATUS.PENDING)
  );
  const grantFailures = batch.changes.filter(
    (c) => c.status === OFFLINE_STATUS.PENDING && c.grantError
  ).length;
  await notifyGmsOfflineBatchSubmitted({
    userName: user.name,
    actorName: actor.name,
    pendingLeft,
    grantFailures
  });
  grantLog("offline.submitBatch.done", {
    pendingLeft,
    grantFailures,
    batchStatuses: batch.changes.map((c) => ({
      changeId: c.changeId,
      operation: c.operation,
      status: c.status,
      itemId: c.itemId || null,
      uuid: c.uuid || null,
      grantError: c.grantError || null
    }))
  });
  // Return every row for this actor so the phone can merge statuses even when
  // the submit only refreshed a change living in an older batch.
  const allForActor = store.batches
    .filter((b) => b.userId === user.id && b.actorId === actorId)
    .flatMap((b) => b.changes.map((c) => ({
      ...c,
      batchId: b.batchId,
      actorId: b.actorId
    })));
  return { accepted: true, batchId, changes: allForActor };
}

export function offlineChangesStatus(user, actorId) {
  getOwnedActor(user, actorId);
  const store = getOfflineChangesStore();
  const changes = store.batches
    .filter((batch) => batch.userId === user.id && batch.actorId === actorId)
    .flatMap((batch) => batch.changes.map((change) => ({
      ...change,
      batchId: batch.batchId,
      actorId: batch.actorId
    })));
  return { changes };
}

export function offlineChangesListPending(user) {
  if (!user.isGM) throw new Error("GM only");
  const store = getOfflineChangesStore();
  return {
    batches: store.batches.filter((batch) =>
      batch.changes.some((change) => change.status === OFFLINE_STATUS.PENDING)
    )
  };
}

/** Owning player withdraws their still-pending queue items (not yet GM-resolved). */
export async function offlineChangesWithdraw(user, actorId, changeIds) {
  getOwnedActor(user, actorId);
  const ids = new Set(
    (Array.isArray(changeIds) ? changeIds : [])
      .map((id) => String(id ?? "").trim())
      .filter(Boolean)
  );
  if (ids.size === 0) return { accepted: true, withdrawn: 0 };

  const store = getOfflineChangesStore();
  let withdrawn = 0;
  for (const batch of store.batches) {
    if (batch.userId !== user.id || batch.actorId !== actorId) continue;
    for (const change of batch.changes) {
      if (!ids.has(change.changeId)) continue;
      if (change.status !== OFFLINE_STATUS.PENDING) continue;
      await undoProvisionalOfflineChange(user, actorId, change, batch);
      change.status = OFFLINE_STATUS.REJECTED;
      change.rejectionReason = "Withdrawn by player";
      change.resolvedAt = Date.now();
      withdrawn += 1;
    }
    batch.updatedAt = Date.now();
  }
  if (withdrawn > 0) await saveOfflineChangesStore(store);
  return { accepted: true, withdrawn };
}

export async function offlineChangeUpdateMatches(batchId, changeId, query) {
  const store = getOfflineChangesStore();
  const batch = store.batches.find((b) => b.batchId === batchId);
  const change = batch?.changes?.find((c) => c.changeId === changeId);
  if (!change) throw new Error("Offline change not found");
  change.matches = await findOfflineCompendiumMatches(change, query, false);
  change.searchQuery = query;
  batch.updatedAt = Date.now();
  await saveOfflineChangesStore(store);
}

/** Undo Trusted+ provisional sheet mutation when GM rejects or player withdraws. */
export async function undoProvisionalOfflineChange(requester, actorId, change, batch = null) {
  if (!requester || !change) return;
  if (change.operation === OFFLINE_OPERATION.SHEET_OVERRIDE) {
    // No-op for rows that never got a provisional apply (below Trusted, or
    // queued before this existed) — there is no effect carrying this changeId.
    if (!change.provisional) return;
    try {
      await undoOfflineSheetOverride(requester, actorId, change);
      grantLog("offline.undo provisional sheet override", {
        changeId: change.changeId,
        kind: change.itemId
      });
    } catch (err) {
      console.warn(`[${MODULE_ID}] undo: could not remove override ${change.itemId}`, err);
    }
    return;
  }
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID && change.itemId) {
    try {
      await actorItemDelete(requester, actorId, change.itemId);
      grantLog("offline.undo provisional item", {
        changeId: change.changeId,
        itemId: change.itemId
      });
    } catch (err) {
      console.warn(`[${MODULE_ID}] undo: could not remove provisional item ${change.itemId}`, err);
    }
    return;
  }
  if (
    change.operation === OFFLINE_OPERATION.CLASS_LEVEL_CHANGE &&
    change.itemId &&
    change.priorLevel != null
  ) {
    try {
      // Advancement reverse removes granted feats/subclass steps; clear picks so we
      // do not re-inject them while leveling down to the pre-provisional level.
      const rollback = {
        ...change,
        quantity: change.priorLevel,
        featUuid: "",
        featName: "",
        subclassUuid: "",
        subclassName: "",
        asiAssignments: ""
      };
      await applyOfflineClassLevelChange(requester, actorId, rollback, batch);
      grantLog("offline.undo provisional level", {
        changeId: change.changeId,
        classId: change.itemId,
        priorLevel: change.priorLevel
      });
    } catch (err) {
      console.warn(`[${MODULE_ID}] undo: could not roll back class level to ${change.priorLevel}`, err);
    }
  }
}

