/**
 * Strings for the approval journals and the whispers that go with them.
 *
 * These are read by the GM, not by the player who caused them, so they follow a
 * world setting rather than whichever phone happened to send the request. The
 * setting can be changed later and the pages rewritten, which is why a page
 * body is never stored as finished prose: it is rebuilt from the request record
 * every time.
 */
export function journalStrings() {
  const code = String(game.settings?.get(MODULE_ID, JOURNAL_LANGUAGE_SETTING) ?? "").toLowerCase();
  return BRIDGE_STRINGS[code] ?? BRIDGE_STRINGS[String(game.i18n?.lang ?? "").slice(0, 2).toLowerCase()] ?? BRIDGE_STRINGS.en;
}

/**
 * Rewrites every logged page in the new language.
 *
 * Names of items and spells are left exactly as they are: they come from
 * compendiums or from what the player typed, and translating those is not ours
 * to do.
 */
export async function rewriteApprovalLogs() {
  try {
    const store = getOfflineChangesStore();
    for (const batch of store.batches ?? []) {
      const actor = game.actors.get(batch.actorId);
      if (!actor) continue;
      for (const change of batch.changes ?? []) {
        await writeApprovalLogEntry(actor, batch, change, { rename: true });
      }
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] could not rewrite the approval logs`, err);
  }
}

/** Escapes text that goes into journal HTML; names are player-written. */
export function escapeLogHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

/**
 * One line saying what a request would do.
 *
 * The wording is translated; the name inside it is not. An item called
 * "Hempen Rope" came from a compendium in whatever language that compendium is
 * written in, and rendering it as anything else would name something that does
 * not exist in this world.
 */
export function describeOfflineChange(change) {
  const t = journalStrings();
  const name = escapeLogHtml(change?.name || change?.itemId || "?");
  const qty = Number(change?.quantity);
  const times = qty > 1 ? ` ×${qty}` : "";
  const op = t.ops[change?.operation];
  if (op) return op(name, qty, times);
  return `${escapeLogHtml(change?.operation ?? "change")} ${name}`;
}

/**
 * The folder every character's approval log lives in, created on first use.
 *
 * Journals rather than a bespoke dialog: the GM already reads and searches
 * journals, they persist without a store of ours, and the history stays
 * readable long after the request was answered.
 */
export async function ensureApprovalLogFolder() {
  const existing = game.folders?.find(
    (folder) => folder.type === "JournalEntry" && folder.name === APPROVAL_LOG_FOLDER
  );
  if (existing) return existing;
  return Folder.create({ name: APPROVAL_LOG_FOLDER, type: "JournalEntry", sorting: "a" });
}

/**
 * The log for one character, created the first time that character asks for
 * something. GM-only: it carries a button that resolves requests, and the
 * decision is the GM's.
 */
export async function ensureApprovalLog(actor) {
  const folder = await ensureApprovalLogFolder();
  const title = actor?.name ?? "Unknown";
  const existing = game.journal?.find(
    (entry) => entry.folder?.id === folder?.id && bridgeFlag(entry, "actorId") === actor.id
  );
  if (existing) return existing;
  return JournalEntry.create({
    name: title,
    folder: folder?.id ?? null,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE },
    flags: { [MODULE_ID]: { actorId: actor.id } }
  });
}

/** One page per request, so a decision rewrites only its own page. */
export function approvalPageName(change) {
  return `${new Date(change.submittedAt ?? Date.now()).toLocaleString()} — ${describeOfflineChange(change)}`;
}

/**
 * The page body. While the request is pending it carries the reject button;
 * once decided it carries the outcome instead.
 *
 * `onclick` would be stripped by Foundry's HTML sanitiser — only `disabled`,
 * `name`, `type`, `value` and `data-*` survive on a button — so the handler is
 * attached from `renderJournalEntryPageSheet` and finds the button by its data.
 */
export function approvalPageContent(batch, change) {
  const t = journalStrings();
  const who = escapeLogHtml(game.users.get(batch.userId)?.name ?? batch.userId);
  const when = new Date(change.submittedAt ?? batch.createdAt ?? Date.now()).toLocaleString();
  const rows = [
    `<p><strong>${describeOfflineChange(change)}</strong></p>`,
    `<p>${t.requestedBy(who, when)}</p>`
  ];
  if (change.grantError) rows.push(`<p><em>${escapeLogHtml(t.failed(change.grantError))}</em></p>`);

  if (change.status === OFFLINE_STATUS.PENDING) {
    // Whether it is already on the sheet is a fact about this row, not about
    // the feature: only a trusted player's request is applied in advance.
    rows.push(`<p>${change.provisional ? t.provisional : t.awaiting}</p>`);
    rows.push(
      `<p><button type="button" data-mb-reject="1"` +
      ` data-mb-batch="${batch.batchId}" data-mb-change="${change.changeId}">${t.reject}</button></p>`
    );
  } else if (change.status === OFFLINE_STATUS.REJECTED) {
    // No reason is offered: there is only one, and printing it added nothing.
    rows.push(`<p><em>${t.rejected}</em></p>`);
  } else if (change.status === OFFLINE_STATUS.APPLIED) {
    rows.push(`<p><em>${t.applied}</em></p>`);
  }
  return rows.join("");
}

/** Writes or rewrites the page describing one request. */
export async function writeApprovalLogEntry(actor, batch, change, { rename = false } = {}) {
  try {
    const journal = await ensureApprovalLog(actor);
    if (!journal) return;
    const content = approvalPageContent(batch, change);
    const existing = journal.pages.find(
      (page) => bridgeFlag(page, "changeId") === change.changeId
    );
    if (existing) {
      // The title carries the same translated sentence as the body, so a
      // language change has to reach it as well.
      const update = { "text.content": content };
      if (rename) update.name = approvalPageName(change);
      await existing.update(update);
      return;
    }
    await journal.createEmbeddedDocuments("JournalEntryPage", [{
      name: approvalPageName(change),
      type: "text",
      text: { content, format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML },
      flags: { [MODULE_ID]: { changeId: change.changeId, batchId: batch.batchId } }
    }]);
  } catch (err) {
    // The log is a convenience; failing to write it must not fail the request.
    console.warn(`[${MODULE_ID}] could not write the approval log`, err);
  }
}

/**
 * Makes the Reject buttons in those journals work.
 *
 * The check is here as well as in the markup: a page is GM-only, but ownership
 * can be changed, and a button that resolves requests should not become one
 * just because someone was given read access.
 */
export function registerApprovalLogButtons() {
  Hooks.on("renderJournalEntryPageSheet", (app, element) => {
    const root = element instanceof HTMLElement ? element : element?.[0];
    if (!root) return;
    for (const button of root.querySelectorAll("button[data-mb-reject]")) {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        const t = journalStrings();
        if (!game.user?.isGM) {
          ui.notifications?.warn(t.onlyGm);
          return;
        }
        button.disabled = true;
        try {
          await offlineChangesResolve(
            game.user,
            button.dataset.mbBatch,
            button.dataset.mbChange,
            "reject"
          );
          ui.notifications?.info(t.rejectDone);
        } catch (err) {
          button.disabled = false;
          ui.notifications?.error(t.rejectFailed(err?.message ?? err));
        }
      });
    }
    for (const button of root.querySelectorAll("button[data-mb-revoke]")) {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        const t = journalStrings();
        if (!game.user?.isGM) {
          ui.notifications?.warn(t.onlyGm);
          return;
        }
        button.disabled = true;
        try {
          await revokeChange(game.user, button.dataset.mbChange);
          ui.notifications?.info(t.revokeDone ?? "Change revoked.");
        } catch (err) {
          button.disabled = false;
          ui.notifications?.error((t.revokeFailed ?? ((w) => `Could not revoke: ${w}`))(err?.message ?? err));
        }
      });
    }
  });
}

/* ------------------------------------------------------------------ *
 * Revocable direct changes
 *
 * Players edit the sheet directly instead of queueing for GM approval; every
 * edit is applied at once and written to the character's log with a Revoke
 * button, so the GM can take any single one back. The undo data a change needs
 * to be reversed is captured at apply time and stored alongside it.
 * ------------------------------------------------------------------ */

export const REVOCABLE_STATUS = Object.freeze({ APPLIED: "applied", REVOKED: "revoked" });

export function getRevocableStore() {
  const raw = game.settings.get(MODULE_ID, REVOCABLE_CHANGES_SETTING) ?? { entries: [] };
  if (!Array.isArray(raw.entries)) raw.entries = [];
  return raw;
}

export async function saveRevocableStore(store) {
  await game.settings.set(MODULE_ID, REVOCABLE_CHANGES_SETTING, store);
}

/**
 * Key that marks two changes as "the same edit repeated" for the purpose of
 * folding a run of them into one log entry: same player, same character, same
 * operation, same target. Only the absolute-set operations that carry a prior
 * value coalesce — a run of quantity nudges, currency edits, slot edits or
 * level bumps. Creates and deletes each touch a different thing, so they never
 * fold. Returns null when the change must never coalesce.
 */
export function revocableCoalesceKey(userId, actorId, undo) {
  const op = undo?.operation;
  let target;
  if (op === "item.quantity") target = undo.itemId;
  else if (op === "currency.set") target = undo.key;
  else if (op === "spellSlots.set") target = undo.slotKey;
  else if (op === "ability.set") target = undo.key;
  // class.level and sheet.override are left out on purpose: class.level's summary
  // reads "level A → B" (folding would leave a stale "from"), and a sheet override
  // captures per-apply undo data (replaced effects) that a fold would mismatch.
  else return null;
  if (!target) return null;
  return `${userId}|${actorId}|${op}|${target}`;
}

/**
 * Is this change a net gain for the player — the only kind worth keeping a
 * Revoke for? A player will happily spend money, use up spell slots or drop an
 * item; nobody cheats themselves *worse*, so those need no undo. Only gains
 * (more of something, an item added, a level up) are recorded and revocable.
 */
export function isRevocableGain(undo) {
  switch (undo?.operation) {
    case "item.create": return true;
    case "item.delete": return false;
    case "item.quantity":
    case "currency.set":
    case "spellSlots.set":
    case "ability.set":
      return Number(undo.newValue) > Number(undo.prior);
    case "class.level":
      return Number(undo.newLevel) > Number(undo.priorLevel);
    // sheet.override gain is decided per kind before the entry is built
    // (sheetOverrideGain), so anything recorded here is already a gain.
    case "sheet.override": return true;
    default: return true; // unknown: keep, to be safe
  }
}

/** Local calendar day of a timestamp, used to group a day's changes on one page. */
export function revocableDayKey(ts) {
  return new Date(ts ?? Date.now()).toLocaleDateString();
}

/**
 * Records a directly-applied sheet change on its day's log page. `undo` carries
 * everything reverseRevocableChange needs. Best-effort: a logging failure never
 * fails the edit the player already made. GM edits are not logged — the GM
 * answers to no one and can undo directly.
 *
 * Three rules keep the log lean:
 *  - Consecutive identical edits (a run of ±1 quantity taps on one item) fold
 *    into the most recent entry; its `undo` — the value from *before the run* —
 *    is kept, so one Revoke takes the whole run back to where it started.
 *  - A change (or a folded run) that ends up no better than it started is not
 *    worth an undo, so it is dropped: never written, or removed if a run turned
 *    a gain back into a loss.
 *  - Entries are grouped one page per day; emptying a day removes its page.
 */
export async function recordRevocableChange(actor, user, summary, undo) {
  if (!actor || !user || user.isGM) return null;
  const store = getRevocableStore();
  const day = revocableDayKey(Date.now());

  const coalesceKey = revocableCoalesceKey(user.id, actor.id, undo);
  if (coalesceKey) {
    const last = store.entries[store.entries.length - 1];
    if (
      last &&
      last.status === REVOCABLE_STATUS.APPLIED &&
      revocableCoalesceKey(last.userId, last.actorId, last.undo) === coalesceKey
    ) {
      // Fold in: keep the run's original `prior`, move the new value forward.
      const prevDay = revocableDayKey(last.at);
      last.summary = String(summary ?? last.summary);
      last.undo = { ...last.undo, newValue: undo.newValue };
      last.at = Date.now();
      const stillAGain = isRevocableGain(last.undo);
      if (!stillAGain) {
        // The run came back to (or below) where it began — no undo needed.
        store.entries = store.entries.filter((e) => e.changeId !== last.changeId);
      }
      try {
        await saveRevocableStore(store);
      } catch (err) {
        console.warn(`[${MODULE_ID}] could not persist coalesced change`, err);
        return stillAGain ? last.changeId : null;
      }
      try {
        await writeRevocableDayPage(actor, revocableDayKey(last.at));
        if (prevDay !== revocableDayKey(last.at)) await writeRevocableDayPage(actor, prevDay);
      } catch (err) {
        console.warn(`[${MODULE_ID}] could not rewrite day log page`, err);
      }
      return stillAGain ? last.changeId : null;
    }
  }

  // A fresh change that leaves the player no better off is never recorded.
  if (!isRevocableGain(undo)) return null;

  const entry = {
    changeId: foundry.utils.randomID(),
    actorId: actor.id,
    userId: user.id,
    userName: user.name,
    operation: undo?.operation ?? "",
    summary: String(summary ?? ""),
    undo: undo ?? {},
    status: REVOCABLE_STATUS.APPLIED,
    at: Date.now()
  };
  try {
    store.entries.push(entry);
    if (store.entries.length > 2000) store.entries = store.entries.slice(-2000);
    await saveRevocableStore(store);
  } catch (err) {
    console.warn(`[${MODULE_ID}] could not persist revocable change`, err);
    return null;
  }
  try {
    await writeRevocableDayPage(actor, day);
  } catch (err) {
    console.warn(`[${MODULE_ID}] could not write day log page`, err);
  }
  return entry.changeId;
}

/** One entry's block within a day page: what changed, by whom, and a Revoke button. */
export function revocableEntryHtml(entry) {
  const t = journalStrings();
  const who = escapeHtml(String(entry.userName ?? entry.userId ?? "Player"));
  const when = new Date(entry.at ?? Date.now()).toLocaleTimeString();
  const rows = [
    `<p><strong>${escapeHtml(entry.summary)}</strong> — ${escapeHtml(`${who} · ${when}`)}</p>`
  ];
  if (entry.status === REVOCABLE_STATUS.REVOKED) {
    rows.push(`<p><em>${escapeHtml(t.revoked ?? "Revoked")}</em></p>`);
    if (entry.revokeError) {
      rows.push(`<p><em>${escapeHtml((t.revokeFailed ?? ((w) => `Could not revoke: ${w}`))(entry.revokeError))}</em></p>`);
    }
  } else {
    rows.push(
      `<p><button type="button" data-mb-revoke="1" data-mb-change="${entry.changeId}">` +
      `${escapeHtml(t.revoke ?? "Revoke")}</button></p>`
    );
  }
  return rows.join("");
}

/**
 * Rewrites (or removes) one character's page for a given day from the store.
 * A day with no entries left — because the last one was dropped as a non-gain —
 * loses its page entirely.
 */
export async function writeRevocableDayPage(actor, day) {
  const journal = await ensureApprovalLog(actor);
  if (!journal) return;
  const store = getRevocableStore();
  const entries = store.entries
    .filter((e) => e.actorId === actor.id && revocableDayKey(e.at) === day)
    .sort((a, b) => (a.at ?? 0) - (b.at ?? 0));
  const page = journal.pages.find((p) => bridgeFlag(p, "revocableDay") === day);
  if (!entries.length) {
    if (page) await journal.deleteEmbeddedDocuments("JournalEntryPage", [page.id]);
    return;
  }
  const content = entries.map(revocableEntryHtml).join("<hr>");
  if (page) {
    await page.update({ "text.content": content });
    return;
  }
  await journal.createEmbeddedDocuments("JournalEntryPage", [{
    name: day,
    type: "text",
    text: { content, format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML },
    flags: { [MODULE_ID]: { revocableDay: day } }
  }]);
}

/** Reverses one applied change using its stored undo data. */
export async function reverseRevocableChange(entry) {
  const undo = entry?.undo ?? {};
  const actor = game.actors.get(entry.actorId);
  if (!actor) throw new Error("Character not found");
  const requester = game.users.get(entry.userId) ?? game.user;
  switch (undo.operation) {
    case "item.create": {
      if (undo.itemId && actor.items.get(undo.itemId)) {
        await actor.deleteEmbeddedDocuments("Item", [undo.itemId]);
      }
      return;
    }
    case "item.delete": {
      if (undo.itemData) await actor.createEmbeddedDocuments("Item", [undo.itemData], { keepId: false });
      return;
    }
    case "item.quantity": {
      const item = undo.itemId ? actor.items.get(undo.itemId) : null;
      if (item) await item.update({ "system.quantity": undo.prior });
      return;
    }
    case "currency.set":
      await actorCurrencyApplyOnActor(actor, undo.key, undo.prior);
      return;
    case "spellSlots.set":
      await actor.update({ [`system.spells.${undo.slotKey}.value`]: undo.prior });
      return;
    case "ability.set":
      // Restore the base score; the apply also cleared any mobile override on it.
      await actor.update({ [`system.abilities.${undo.key}.value`]: undo.prior });
      return;
    case "sheet.override": {
      // Reuse the offline undo, keyed by the original change id so it removes the
      // exact effect this edit created and restores whatever it had displaced.
      const pseudo = {
        itemId: undo.kind,
        changeId: undo.overrideChangeId,
        priorFlatAc: undo.priorFlatAc,
        replacedEffects: undo.replacedEffects
      };
      await undoOfflineSheetOverride(requester, entry.actorId, pseudo);
      return;
    }
    case "class.level": {
      const rollback = {
        operation: OFFLINE_OPERATION.CLASS_LEVEL_CHANGE,
        itemId: undo.classId,
        quantity: undo.priorLevel,
        priorLevel: undo.priorLevel,
        featUuid: "", featName: "", subclassUuid: "", subclassName: "", asiAssignments: ""
      };
      await applyOfflineClassLevelChange(requester, entry.actorId, rollback, null);
      return;
    }
    default:
      throw new Error(`Cannot revoke: unknown operation ${undo.operation}`);
  }
}

export async function revokeChange(user, changeId) {
  if (!user?.isGM) throw new Error("GM only");
  const store = getRevocableStore();
  const entry = store.entries.find((e) => e.changeId === changeId);
  if (!entry) throw new Error("Change not found");
  if (entry.status === REVOCABLE_STATUS.REVOKED) return { accepted: true, entry };
  try {
    await reverseRevocableChange(entry);
    entry.status = REVOCABLE_STATUS.REVOKED;
    entry.revokedAt = Date.now();
    entry.revokeError = null;
  } catch (err) {
    entry.revokeError = String(err?.message ?? err);
    await saveRevocableStore(store);
    await writeRevocableDayPage(game.actors.get(entry.actorId), revocableDayKey(entry.at));
    throw err;
  }
  await saveRevocableStore(store);
  await writeRevocableDayPage(game.actors.get(entry.actorId), revocableDayKey(entry.at));
  return { accepted: true, entry };
}

export async function offlineChangesResolve(user, batchId, changeId, decision, options = {}) {
  if (!user.isGM) throw new Error("GM only");
  const store = getOfflineChangesStore();
  const batch = store.batches.find((b) => b.batchId === batchId);
  const change = batch?.changes?.find((c) => c.changeId === changeId);
  if (!batch || !change) throw new Error("Offline change not found");
  if (change.status !== OFFLINE_STATUS.PENDING) {
    return { accepted: true, change };
  }

  if (decision === "reject") {
    const requester = game.users.get(batch.userId);
    await undoProvisionalOfflineChange(requester, batch.actorId, change, batch);
    change.status = OFFLINE_STATUS.REJECTED;
    change.rejectionReason = String(options.reason ?? "").trim() || "Rejected by GM";
    change.resolvedAt = Date.now();
  } else if (decision === "approve") {
    // A failed apply used to leave the row PENDING with no trace: the GM saw a
    // transient toast, the phone kept showing "awaiting review" forever, and
    // nothing recorded why. Persist the reason before rethrowing so the
    // approval dialog and the phone can both show it.
    try {
      await applyOfflineChange(batch, change, options);
    } catch (err) {
      change.grantError = String(err?.message ?? err);
      batch.updatedAt = Date.now();
      await saveOfflineChangesStore(store);
      throw err;
    }
    change.status = OFFLINE_STATUS.APPLIED;
    change.resolvedAt = Date.now();
    change.rejectionReason = null;
    change.grantError = null;
    change.provisional = false;
  } else {
    throw new Error("decision must be approve or reject");
  }

  batch.updatedAt = Date.now();
  await saveOfflineChangesStore(store);
  // The log page carries the button, so it has to lose it now that the request
  // is answered — and say what the answer was.
  await writeApprovalLogEntry(game.actors.get(batch.actorId), batch, change);
  return { accepted: true, change };
}

export async function applyOfflineChange(batch, change, options = {}) {
  const requester = game.users.get(batch.userId);
  if (!requester) throw new Error(`Submitting user not found: ${batch.userId}`);
  grantLog("offline.apply", {
    batchId: batch.batchId,
    changeId: change.changeId,
    operation: change.operation,
    uuid: change.uuid || null,
    itemId: change.itemId || null,
    name: change.name || null,
    itemType: change.itemType || null,
    options: {
      uuid: options.uuid || null,
      custom: !!options.custom,
      query: options.query || null
    }
  });
  if (change.operation === OFFLINE_OPERATION.ITEM_DELETE) {
    await actorItemDelete(requester, batch.actorId, change.itemId);
    return;
  }
  if (change.operation === OFFLINE_OPERATION.ITEM_QUANTITY) {
    await actorItemSetQuantity(requester, batch.actorId, change.itemId, change.quantity);
    return;
  }
  if (change.operation === OFFLINE_OPERATION.CURRENCY_SET) {
    const actor = getOwnedActor(requester, batch.actorId);
    const key = change.itemId ? String(change.itemId).trim() : "";
    if (!key) throw new Error("currency key is required");
    await actorCurrencyApplyOnActor(actor, key, change.quantity);
    return;
  }
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_TEXT && change.itemId) {
    const actor = getOwnedActor(requester, batch.actorId);
    const item = actor.items.get(change.itemId);
    if (!item) throw new Error(`Item not found: ${change.itemId}`);
    const curQtyRaw = Number(item.system?.quantity);
    const safeCur = Number.isFinite(curQtyRaw) ? Math.max(0, Math.floor(curQtyRaw)) : 1;
    const delta = Math.min(ITEM_QUANTITY_MAX, Math.max(1, Math.floor(Number(change.quantity) || 0)));
    const newQty = Math.min(ITEM_QUANTITY_MAX, safeCur + delta);
    await actorItemSetQuantity(requester, batch.actorId, change.itemId, newQty);
    return;
  }
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID) {
    const uuid = String(options.uuid || change.uuid || "").trim();
    if (!uuid) throw new Error("uuid is required for item.createFromUuid");
    // Trusted+ provisional create already put the item on the sheet.
    if (change.itemId) {
      const actor = getOwnedActor(requester, batch.actorId);
      if (actor.items.get(change.itemId)) return;
    }
    const created = await actorItemCreate(requester, batch.actorId, uuid, change.name);
    if (created?.itemId) change.itemId = created.itemId;
    return;
  }
  if (change.operation === OFFLINE_OPERATION.CLASS_LEVEL_CHANGE) {
    // Trusted+ may already be at the queued target; Approve only clears PENDING.
    const result = await applyOfflineClassLevelChange(requester, batch.actorId, change, batch);
    if (change.priorLevel == null && result.priorLevel != null) {
      change.priorLevel = result.priorLevel;
    }
    return;
  }
  if (change.operation === OFFLINE_OPERATION.ABILITY_SET) {
    await applyOfflineAbilitySet(requester, batch.actorId, change);
    return;
  }
  if (change.operation === OFFLINE_OPERATION.SHEET_OVERRIDE) {
    // Trusted+ submits already put this on the actor; Approve just confirms it.
    // Rows queued before provisional application existed, and rows from players
    // below Trusted, have no effect yet and still need applying here.
    if (change.provisional) {
      grantLog("offline.sheetOverride.approve (already provisional, no re-apply)", {
        changeId: change.changeId,
        kind: change.itemId
      });
      return;
    }
    await applyOfflineSheetOverride(requester, batch.actorId, change);
    return;
  }
  // BIOGRAPHY_SET deliberately has no branch: it resolves to APPLIED or REJECTED
  // during submit, so it can never be sitting PENDING for a GM to approve here.
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_TEXT) {
    if (options.custom) {
      grantLog("offline.apply CREATE_TEXT as custom", {
        changeId: change.changeId,
        name: change.name,
        itemType: change.itemType
      });
      await actorItemCreateCustom(requester, batch.actorId, change, options.customName);
      return;
    }
    let uuid = options.uuid ? String(options.uuid) : "";
    if (!uuid) {
      const query = String(options.query ?? change.searchQuery ?? change.name ?? "").trim();
      const matches = await findOfflineCompendiumMatches(change, query, true);
      if (matches.length !== 1) {
        throw new Error(`Expected one exact compendium match for "${query}", got ${matches.length}. Use custom item or refine search.`);
      }
      uuid = matches[0].uuid;
    }
    await actorItemCreate(requester, batch.actorId, uuid, change.name);
    return;
  }
  throw new Error(`Unsupported offline operation: ${change.operation}`);
}

export function parseAsiAssignments(raw) {
  if (!raw || typeof raw !== "string") return {};
  try {
    const obj = JSON.parse(raw);
    if (!obj || typeof obj !== "object" || Array.isArray(obj)) return {};
    const out = {};
    for (const [key, val] of Object.entries(obj)) {
      const k = String(key).toLowerCase();
      if (!["str", "dex", "con", "int", "wis", "cha"].includes(k)) continue;
      const n = Math.floor(Number(val));
      if (!Number.isFinite(n) || n === 0) continue;
      out[k] = Math.min(2, Math.max(-2, n));
    }
    return out;
  } catch {
    return {};
  }
}

export function isTrustedBridgeUser(user) {
  return (user?.role ?? 0) >= CONST.USER_ROLES.TRUSTED;
}

/**
 * Apply a queued absolute class-level target via AdvancementManager.
 * Prefers level-up prep (feat / ASI assignments / subclass); sibling ability.set
 * in the same batch can fill ASI when prep has no assignments.
 */
export async function applyOfflineClassLevelChange(user, actorId, change, batch = null) {
  const classId = change?.itemId ? String(change.itemId) : "";
  if (!classId) throw new Error("classId is required for class.levelChange");
  const actor = getOwnedActor(user, actorId);
  const classItem = actor.items.get(classId);
  if (!classItem || classItem.type !== "class") {
    throw new Error(`Class item not found on actor: ${classId}`);
  }
  const current = Math.max(0, Math.floor(Number(classItem.system?.levels) || 0));
  const target = Math.min(CLASS_LEVEL_MAX, Math.max(0, Math.floor(Number(change.quantity) || 0)));
  const delta = target - current;
  if (delta === 0) return { applied: false, priorLevel: current, targetLevel: target };

  let asiAssignments = parseAsiAssignments(change.asiAssignments);
  const consumedAbilityChangeIds = [];
  // Map pending ability.set in this batch into ASI deltas when prep has none.
  if (!Object.keys(asiAssignments).length && !String(change.featUuid ?? "").trim() && batch?.changes) {
    for (const sibling of batch.changes) {
      if (sibling.status !== OFFLINE_STATUS.PENDING) continue;
      if (sibling.operation !== OFFLINE_OPERATION.ABILITY_SET) continue;
      const key = String(sibling.itemId ?? "").toLowerCase();
      if (!["str", "dex", "con", "int", "wis", "cha"].includes(key)) continue;
      const base = Number(actor.system?.abilities?.[key]?.value) || 10;
      const targetScore = Math.min(
        ABILITY_SCORE_MAX,
        Math.max(ABILITY_SCORE_MIN, Math.floor(Number(sibling.quantity) || base))
      );
      const d = targetScore - base;
      if (d === 0) continue;
      asiAssignments[key] = (asiAssignments[key] || 0) + d;
      consumedAbilityChangeIds.push(sibling.changeId);
    }
    // Cap total positive ASI points at 2 (standard improvement).
    let pos = Object.values(asiAssignments).filter((v) => v > 0).reduce((a, b) => a + b, 0);
    if (pos > 2) {
      asiAssignments = {};
      consumedAbilityChangeIds.length = 0;
    }
  }

  const picks = {
    featUuid: String(change.featUuid ?? "").trim(),
    subclassUuid: String(change.subclassUuid ?? "").trim(),
    asiAssignments
  };
  await runAdvancementToCompletion(user, actorId, classId, delta, picks);

  for (const id of consumedAbilityChangeIds) {
    const sibling = batch.changes.find((c) => c.changeId === id);
    if (!sibling || sibling.status !== OFFLINE_STATUS.PENDING) continue;
    sibling.status = OFFLINE_STATUS.APPLIED;
    sibling.resolvedAt = Date.now();
    sibling.rejectionReason = null;
  }
  return { applied: true, priorLevel: current, targetLevel: target };
}

/**
 * Payload for a non-automatic step during unattended offline apply.
 * Uses level-up prep picks when AdvancementManager offers matching steps.
 */
export function offlineAdvancementStepData(step, picks = {}) {
  const flow = step?.flow;
  const advancement = flow?.advancement;
  if (!flow || !advancement) return {};
  const advancementType = advancement.constructor?.typeName
    ?? advancement.type
    ?? advancement.constructor?.name
    ?? "";
  const level = step.class?.level ?? flow.level ?? 0;
  if (advancementType === "HitPoints" || advancement.constructor?.name === "HitPointsAdvancement") {
    return { [level]: "avg" };
  }
  if (
    advancementType === "AbilityScoreImprovement" ||
    advancement.constructor?.name === "AbilityScoreImprovementAdvancement"
  ) {
    if (picks.featUuid) return { type: "feat", featUuid: picks.featUuid };
    const assignments = picks.asiAssignments && typeof picks.asiAssignments === "object"
      ? picks.asiAssignments
      : {};
    if (Object.keys(assignments).length) return { type: "asi", assignments };
    return {};
  }
  if (advancementType === "Subclass" || advancement.constructor?.name === "SubclassAdvancement") {
    if (picks.subclassUuid) return { uuid: picks.subclassUuid };
    return {};
  }
  return {};
}

/**
 * Begin → auto-walk every remaining step with prep picks / defaults → commit.
 * Reuses the same session path as the interactive mobile wizard.
 */
export async function runAdvancementToCompletion(user, actorId, classId, delta, picks = {}) {
  let result = await classAdvancementBegin(user, actorId, classId, delta);
  let guard = 0;
  while (!result.done && guard++ < 80) {
    const session = getAdvancementSession(user, result.sessionId);
    const step = session.manager.steps[session.stepIndex];
    const data = offlineAdvancementStepData(step, picks);
    result = await classAdvancementSubmit(user, result.sessionId, data);
  }
  if (!result.done) {
    await classAdvancementCancel(user, result.sessionId);
    throw new Error("Offline level change stalled before completion (too many steps)");
  }
  await classAdvancementCommit(user, result.sessionId);
}

/**
 * Standalone ability score → write base actor value (not ActiveEffect).
 * AE OVERRIDE left the edit-mode toggle showing the old score while rolls used
 * the overridden total — confusing and hard to reverse.
 */
export async function applyOfflineAbilitySet(user, actorId, change) {
  const key = String(change?.itemId ?? "").toLowerCase();
  if (!["str", "dex", "con", "int", "wis", "cha"].includes(key)) {
    throw new Error(`Invalid ability key: ${change?.itemId}`);
  }
  const score = Math.min(
    ABILITY_SCORE_MAX,
    Math.max(ABILITY_SCORE_MIN, Math.floor(Number(change.quantity) || 10))
  );
  const actor = getOwnedActor(user, actorId);
  const abilityKey = `system.abilities.${key}.value`;
  await removeMobileOverrideEffects(
    actor,
    (effect) => (effect.changes ?? []).some((c) => c.key === abilityKey)
  );
  await actor.update({ [abilityKey]: score });
}

/**
 * Every sheet.override kind this module can apply. Checked when the batch is
 * submitted, not only when the GM approves: an app newer than the deployed
 * module would otherwise queue a row that looks fine in the approval dialog,
 * fail on Approve, and sit PENDING forever with the phone's banner stuck.
 */
export const SHEET_OVERRIDE_KINDS = new Set([
  "ac.bonus", "init.bonus", "attributes.prof",
  "skill.prof", "save.prof",
  "speed.walk", "speed.fly", "speed.swim", "speed.climb",
  "sense.blindsight", "sense.darkvision", "sense.tremorsense", "sense.truesight",
  "trait.dr", "trait.di", "trait.dv", "trait.ci"
]);

/**
 * Map sheet.override kinds → dnd5e ActiveEffect change entries.
 * Senses use flat `system.attributes.senses.<type>` (dnd5e schema in this world).
 */
export function mapSheetOverrideToAeChanges(change) {
  const kind = String(change?.itemId ?? "").trim();
  const n = Math.floor(Number(change?.quantity) || 0);
  const token = String(change?.summary ?? "").trim().toLowerCase();
  const ADD = CONST.ACTIVE_EFFECT_MODES.ADD;
  const OVERRIDE = CONST.ACTIVE_EFFECT_MODES.OVERRIDE;
  const UPGRADE = CONST.ACTIVE_EFFECT_MODES.UPGRADE;

  const sense = (senseKey) => [{
    key: `system.attributes.senses.${senseKey}`,
    mode: UPGRADE,
    value: String(Math.max(0, n))
  }];
  const speed = (moveKey) => [{
    key: `system.attributes.movement.${moveKey}`,
    mode: OVERRIDE,
    value: String(Math.max(0, n))
  }];
  const trait = (traitKey) => {
    if (!token) throw new Error(`summary (damage/condition type) required for ${kind}`);
    return [{ key: `system.traits.${traitKey}.value`, mode: ADD, value: token }];
  };

  switch (kind) {
    case "ac.bonus":
      return [{ key: "system.attributes.ac.bonus", mode: ADD, value: String(n) }];
    case "init.bonus":
      return [{ key: "system.attributes.init.bonus", mode: ADD, value: String(n) }];
    case "attributes.prof":
      return [{ key: "system.attributes.prof", mode: OVERRIDE, value: String(Math.max(0, n)) }];
    case "skill.prof": {
      // OVERRIDE so "none" (0) clears proficiency; quantity is 0 / 1 / 2.
      if (!/^[a-z]{3}$/.test(token)) {
        throw new Error(`summary (skill id) required for ${kind}`);
      }
      const tier = Math.max(0, Math.min(2, n));
      return [{
        key: `system.skills.${token}.value`,
        mode: OVERRIDE,
        value: String(tier)
      }];
    }
    case "save.prof": {
      // dnd5e models save proficiency as abilities.<abl>.proficient (0 or 1 —
      // no expertise tier), multiplied by the proficiency bonus in
      // prepareAbilities. OVERRIDE so 0 can also strip an inherited proficiency.
      if (!ABILITY_KEYS.has(token)) {
        throw new Error(`summary (ability id) required for ${kind}`);
      }
      return [{
        key: `system.abilities.${token}.proficient`,
        mode: OVERRIDE,
        value: String(Math.max(0, Math.min(1, n)))
      }];
    }
    case "speed.walk": return speed("walk");
    case "speed.fly": return speed("fly");
    case "speed.swim": return speed("swim");
    case "speed.climb": return speed("climb");
    case "sense.blindsight": return sense("blindsight");
    case "sense.darkvision": return sense("darkvision");
    case "sense.tremorsense": return sense("tremorsense");
    case "sense.truesight": return sense("truesight");
    case "trait.dr": return trait("dr");
    case "trait.di": return trait("di");
    case "trait.dv": return trait("dv");
    case "trait.ci": return trait("ci");
    default:
      // Adding a case here means adding the kind to SHEET_OVERRIDE_KINDS too,
      // otherwise the submit gate above rejects it before it ever gets here.
      throw new Error(`Unsupported sheet.override kind: ${kind}`);
  }
}

/**
 * Write the override onto the actor. Safe to call more than once for the same
 * change row: sheet overrides are applied provisionally at submit time and the
 * GM's Approve may run this again on an older row, so every path here has to be
 * idempotent rather than additive.
 */
export async function applyOfflineSheetOverride(user, actorId, change) {
  const kind = String(change?.itemId ?? "").trim();
  const n = Math.floor(Number(change?.quantity) || 0);
  const actor = getOwnedActor(user, actorId);

  // Flat AC ignores attributes.ac.bonus — write flat directly.
  if (kind === "ac.bonus") {
    const ac = actor.system?.attributes?.ac ?? {};
    if (ac.calc === "flat") {
      const current = Math.floor(Number(ac.flat ?? ac.value ?? 10) || 10);
      // The only non-ActiveEffect override, so it is the only one that can
      // stack. Always compute from the value this row first saw, and remember
      // that value so a rejection can put it back exactly.
      const prior = Number.isFinite(Number(change.priorFlatAc))
        ? Math.floor(Number(change.priorFlatAc))
        : current;
      if (change.priorFlatAc == null) change.priorFlatAc = prior;
      await actor.update({
        "system.attributes.ac.flat": Math.max(0, prior + n)
      });
      return;
    }
  }

  const aeChanges = mapSheetOverrideToAeChanges(change);
  const label = String(change?.name ?? "").trim()
    || `${change.itemId}: ${change.summary || change.quantity}`;
  // Replace prior Mobile AE for the same keys so re-edits don't stack.
  const keys = new Set(aeChanges.map((c) => c.key));
  const displaces = (effect, flag) =>
    flag.changeId !== change.changeId
    && (effect.changes ?? []).some((c) => keys.has(c.key));
  // An earlier, already-approved override of the same kind is about to be
  // deleted. Snapshot it once so rejecting THIS row restores that value rather
  // than clearing the field outright. Only on the first apply — a re-edit must
  // not overwrite the snapshot with its own intermediate state.
  if (change.replacedEffects == null) {
    change.replacedEffects = mobileOverrideEffectsMatching(actor, displaces)
      .map((effect) => {
        const data = effect.toObject();
        delete data._id;
        return data;
      });
  }
  await removeMobileOverrideEffects(
    actor,
    (effect) => (effect.changes ?? []).some((c) => keys.has(c.key))
  );
  await createMobileOverrideEffect(user, actorId, {
    name: `Mobile: ${label}`,
    changeId: change.changeId,
    changes: aeChanges
  });
}

/**
 * Remove a provisionally applied sheet override. Effects are matched by the
 * `changeId` stamped into their module flag, never by the change key alone —
 * an effect a GM built by hand can target the same key and must survive.
 */
export async function undoOfflineSheetOverride(user, actorId, change) {
  const kind = String(change?.itemId ?? "").trim();
  const actor = getOwnedActor(user, actorId);

  // Flat AC was a direct write, so there is no effect to delete.
  if (kind === "ac.bonus" && change.priorFlatAc != null) {
    const ac = actor.system?.attributes?.ac ?? {};
    if (ac.calc === "flat") {
      await actor.update({
        "system.attributes.ac.flat": Math.max(0, Math.floor(Number(change.priorFlatAc)))
      });
    }
    return;
  }

  await removeMobileOverrideEffects(
    actor,
    (effect, flag) => flag.changeId === change.changeId
  );
  // Put back whatever this row displaced when it was first applied.
  if (Array.isArray(change.replacedEffects) && change.replacedEffects.length > 0) {
    await actor.createEmbeddedDocuments("ActiveEffect", change.replacedEffects);
  }
}

/**
 * Mobile-created override effects on this actor matching `predicate` (all of
 * them when no predicate is given). Only effects carrying our `offlineOverride`
 * flag are ever considered, so an effect a GM authored by hand is never touched.
 */
export function mobileOverrideEffectsMatching(actor, predicate) {
  return (actor.effects?.contents ?? [...(actor.effects ?? [])]).filter((effect) => {
    const flag = bridgeFlags(effect);
    if (!flag?.offlineOverride) return false;
    return typeof predicate === "function" ? !!predicate(effect, flag) : true;
  });
}

export async function removeMobileOverrideEffects(actor, predicate) {
  const ids = mobileOverrideEffectsMatching(actor, predicate)
    .map((effect) => effect.id)
    .filter(Boolean);
  if (ids.length) {
    await actor.deleteEmbeddedDocuments("ActiveEffect", ids);
  }
}

export async function createMobileOverrideEffect(user, actorId, { name, changeId, changes }) {
  getOwnedActor(user, actorId);
  const actor = game.actors.get(actorId);
  if (!actor) throw new Error("Actor not found");
  if (!Array.isArray(changes) || changes.length === 0) {
    throw new Error("ActiveEffect changes required");
  }
  const effectData = {
    name: name || "Mobile override",
    img: "icons/svg/upgrade.svg",
    origin: actor.uuid,
    disabled: false,
    transfer: false,
    changes: changes.map((c) => ({
      key: String(c.key ?? ""),
      mode: Number(c.mode) || CONST.ACTIVE_EFFECT_MODES.OVERRIDE,
      value: String(c.value ?? ""),
      priority: c.priority ?? null
    })),
    flags: {
      [MODULE_ID]: {
        offlineOverride: true,
        changeId: changeId || null
      }
    }
  };
  await actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
}

export async function actorItemCreateCustom(user, actorId, change, customName = null) {
  const actor = getOwnedActor(user, actorId);
  const name = String(customName ?? change.name ?? "").trim();
  if (!name) throw new Error("Custom item name is required");
  const allowedTypes = new Set(game.documentTypes?.Item ?? []);
  let type = change.isSpell ? "spell" : (change.itemType || "loot");
  // Refuse invalid subtypes (e.g. "Ammunition") so Foundry does not coerce into
  // an empty consumable stub that looks usable but has no weapon damage.
  if (!change.isSpell && allowedTypes.size && !allowedTypes.has(type)) {
    grantWarn("createCustom invalid itemType coerced to loot", {
      requested: type,
      allowedSample: [...allowedTypes].slice(0, 12)
    });
    type = "loot";
  }
  grantLog("createCustom.start", {
    user: user?.name,
    actorId,
    name,
    type,
    quantity: change.quantity,
    isSpell: !!change.isSpell,
    changeId: change.changeId || null
  });
  const system = {};
  if (change.isSpell) {
    system.level = Math.max(0, Math.min(Number(change.spellLevel) || 0, 9));
    if (change.spellSchool) system.school = change.spellSchool;
    system.preparation = { mode: "prepared", prepared: true };
    if (change.summary) system.description = { value: change.summary };
  } else {
    system.quantity = Math.min(ITEM_QUANTITY_MAX, Math.max(1, Math.floor(Number(change.quantity) || 1)));
    if (change.summary || change.chatDescription) {
      system.description = {
        value: change.summary ?? "",
        chat: change.chatDescription ?? ""
      };
    }
    const weight = Number(change.weight);
    if (Number.isFinite(weight) && weight >= 0) {
      system.weight = { value: weight, units: "lb" };
    }
    const price = Number(change.price);
    if (Number.isFinite(price) && price >= 0) {
      const denomination = String(change.priceDenomination ?? "gp").trim() || "gp";
      system.price = { value: price, denomination };
    }
  }
  const itemData = { name, type, system };
  if (change.img) itemData.img = change.img;
  const created = await actor.createEmbeddedDocuments("Item", [itemData]);
  const first = created?.[0];
  grantLog("createCustom.done", summarizeGrantItem(first, "customOwned"));
  return {
    accepted: true,
    itemId: first?.id ?? null,
    name: first?.name ?? name,
    img: first ? routeDocumentImg(first) : null
  };
}

/**
 * Replace the actor's own portrait. Same upload path and the same permission
 * as item art; the actor sheet in the browser lets an owner do exactly this.
 */
